// Fill remaining slots 152–300 procedurally for complete roster
const TYPES = ['Fire','Water','Grass','Electric','Ice','Dragon','Dark','Light','Ghost','Rock','Steel','Wind','Poison','Psychic'];
const RARITIES = ['common','common','common','uncommon','uncommon','rare'];
const HABITATS = ['forest','cave','ocean','mountain','volcano','tundra','swamp','desert','sky','dungeon'];
const NAMES_PREFIX = ['Blaze','Frost','Storm','Shadow','Void','Solar','Terra','Aqua','Zephyr','Cryo','Pyro','Neon','Flux','Gale','Tide','Spark','Ember','Crystal','Iron','Venom','Mystic','Radiant','Phantom','Thunder','Glyph','Rune','Prism','Echo','Nova','Lunar'];
const NAMES_SUFFIX = ['paw','horn','fang','claw','wing','tail','maw','crest','back','fin','brow','eye','breath','heart','hide','shell','spike','mane','jaw','strike'];

for (let id = 152; id <= 300; id++) {
  const prefix = NAMES_PREFIX[(id * 7) % NAMES_PREFIX.length];
  const suffix = NAMES_SUFFIX[(id * 13) % NAMES_SUFFIX.length];
  const primaryType = TYPES[(id * 3) % TYPES.length];
  const secondaryType = id % 3 === 0 ? TYPES[(id * 7 + 2) % TYPES.length] : undefined;
  const rarity = RARITIES[id % RARITIES.length];
  const stage = id % 4 === 0 ? 3 : id % 3 === 0 ? 2 : 1;
  const hp = 40 + (id % 60);
  const atk = 40 + ((id * 3) % 80);
  const def = 38 + ((id * 5) % 75);
  const spAtk = 40 + ((id * 7) % 85);
  const spDef = 38 + ((id * 11) % 75);
  const spd = 35 + ((id * 9) % 90);

  MONSTERS.push({
    monsterId: id,
    name: `${prefix}${suffix}`,
    types: { primary: primaryType, ...(secondaryType && secondaryType !== primaryType ? { secondary: secondaryType } : {}) },
    rarity,
    evolutionStage: stage,
    catchRate: rarity === 'legendary' ? 3 : rarity === 'epic' ? 12 : rarity === 'rare' ? 25 : rarity === 'uncommon' ? 45 : 55,
    expYield: 60 + (id % 200),
    habitat: HABITATS[id % HABITATS.length],
    description: `A ${rarity} ${primaryType}-type monster discovered in the wild. Trainers prize it for its ${atk > spAtk ? 'physical strength' : 'special power'}.`,
    baseStats: { hp, attack: atk, defense: def, specialAttack: spAtk, specialDefense: spDef, speed: spd },
    appearance: { colorPalette: ['#' + ((id * 12345) % 0xFFFFFF).toString(16).padStart(6,'0'), '#' + ((id * 67890) % 0xFFFFFF).toString(16).padStart(6,'0')] },
  });
}

module.exports = MONSTERS;
